{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, count(*) n, min(value) vmin, max(value) vmax FROM abnormal_metrics WHERE service_name='search' AND metric IN ('k8s.container.ready','k8s.container.restarts','k8s.deployment.available') GROUP BY metric",
          "claim": "Search container never ready (ready=0, deployment available=0) while restarts climbed from 3 to 6 in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name='search' GROUP BY service_name",
          "claim": "Search emits no spans in the abnormal period, though it had about 650 server spans in normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, attr_status_code st, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND (span_name='search.Search/Nearby' OR span_name='HTTP /hotels') GROUP BY ALL ORDER BY 1,2,3,4",
          "claim": "673 of 678 frontend search.Search/Nearby client calls error in about 0.025 ms, and the matching /hotels server spans return HTTP 500."
        }
      ]
    }
  ]
}
